import React,{useContext} from "react";
import "./Experiance.css"
import { themeContext } from "../../contex";

export const Experiance=()=>{

    const theme = useContext(themeContext);
    const darkMode = theme.state.darkMode;
    const circleClass = darkMode ? "circle dark" : "circle";
    let styleObj={
        color:darkMode?"":"black",
    }

    return (
       <div className="experiance" id="experiance">

        <h1 className='experiance-text' style={styleObj}>Experiance</h1>

        <div className="expriance-details">
            <div className="expriance-details-1">
            <span id="experiance-detail-intro">
                Kelsa.io
                <br/>
                Full Stack Web Developer
                <br/>
                Dec 2023 - March 2024
                <br/>
          Accomplished Full Stack Web Developer with
expertise in designing<br/> Implementing, and maintaining
scalable and dynamic web applications.<br/> Proficient in
both front-end and back-end technologies,<br/> adept at
delivering innovative solutions that optimize user
experiences and drive business objectives<br/>
            </span>
            </div>

        <div className="achievement">
            <div className={circleClass}>1+</div>
            <span>Years</span>
            <span>Experiance</span>
        </div>

        </div>
  
     

       </div>
    )
}